import logoMark from '../assets/logo-mark.png'

/** The WisprRam wave mark (generated by client/build/make-icons.py). Decorative next to the name. */
export function LogoMark({ height = 26, className }: { height?: number; className?: string }): React.JSX.Element {
  return <img src={logoMark} alt="" aria-hidden="true" draggable={false} className={['logo-mark', className].filter(Boolean).join(' ')} style={{ height }} />
}

export function Brand(): React.JSX.Element {
  return (
    <div className="brand" title="WisprRam: Wispr to your RAM">
      <LogoMark />
      WisprRam
    </div>
  )
}
